const shop=function(){const q=params();const cat=q.get('category')||'All Categories';const term=window.shopSearch||'';let list=products.filter(function(p){const goodCat=cat==='All Categories'||p.category===cat;const goodTerm=!term||(p.name+' '+p.category).toLowerCase().includes(term.toLowerCase());return goodCat&&goodTerm});if(window.shopSort==='low')list.sort(function(a,b){return a.price-b.price});if(window.shopSort==='high')list.sort(function(a,b){return b.price-a.price});return crumb(cat==='All Categories'?'Shop':cat,'Shop ›')+'<main class="container inner-page"><div class="account-layout"><aside class="panel" style="padding:19px;height:max-content"><h3 style="font-size:15px;font-weight:600;margin:0 0 12px">All Categories</h3>'+cats.map(function(c){return '<a href="#/shop-01?category='+encodeURIComponent(c[0])+'" style="display:block;padding:9px 0;border-bottom:1px solid #eee;font-size:11px;color:'+(c[0]===cat?'#00a907':'#777')+'">'+c[0]+'</a>'}).join('')+'<div style="margin-top:20px"><strong style="font-size:12px">Filter by price</strong><p style="font-size:11px;color:#888">Fresh groceries, selected for quality</p></div></aside><section><div class="panel-heading" style="padding:0 0 15px;border-bottom:1px solid #eee;margin-bottom:18px"><span style="font-size:12px;color:#777">Showing '+list.length+' products</span><select id="sort-select" class="field-input" style="padding:8px;border:1px solid #eee;border-radius:4px;font-size:11px"><option value="featured">Sort by: Featured</option><option value="low">Price: Low to High</option><option value="high">Price: High to Low</option></select></div><div class="product-grid">'+(list.length?list.map(productCard).join(''):'<div class="panel" style="padding:30px">No products found. Try another category or search.</div>')+'</div></section></div></main>'};
const productPage=function(){const p=product(params().get('id')||1);return crumb(p.name,'Shop › '+p.category+' ›')+'<main class="container inner-page"><div class="product-detail"><div class="detail-image"><img src="'+img(p.img,1000)+'" alt="'+esc(p.name)+'"></div><section class="detail-copy"><div class="product-cat">'+p.category+' / Fresh market</div><h1>'+esc(p.name)+'</h1><div class="stars">★★★★★ &nbsp;<span style="color:#888">4.8 Customer Reviews</span></div><div class="detail-price">'+money(p.price)+' <del style="font-size:14px;color:#aaa;margin-left:8px">'+(p.old?money(p.old):'')+'</del></div><p>'+p.desc+'</p><p>✓ &nbsp;Freshly selected and carefully packed<br>✓ &nbsp;Delivered with freshness in mind<br>✓ &nbsp;30 day satisfaction guarantee</p><div class="detail-actions"><div class="qty"><button data-quantity="-1">−</button><input id="product-qty" value="1" readonly><button data-quantity="1">+</button></div><button class="form-button" data-add="'+p.id+'" data-detail-add>Add to Cart</button><button class="wish-btn '+(wishes.includes(p.id)?'active':'')+'" data-wish="'+p.id+'">♡</button></div><div style="font-size:11px;color:#888">Category: <a class="text-link" href="#/shop-01?category='+encodeURIComponent(p.category)+'">'+p.category+'</a></div></section></div><section class="section">'+sectionHead('YOU MAY ALSO LIKE','Related Products','','shop-01')+'<div class="product-grid">'+products.filter(function(x){return x.id!==p.id}).slice(0,4).map(productCard).join('')+'</div></section></main>'};
const dashboard=function(){const sampleOrders=JSON.parse(localStorage.getItem('shopery-orders')||'[]');const rows=(sampleOrders.length?sampleOrders:[{id:'738',date:'08 Sep, 2026',total:135,count:5,status:'Processing'},{id:'703',date:'24 May, 2026',total:25,count:1,status:'On the way'},{id:'130',date:'22 Apr, 2026',total:250,count:4,status:'Completed'}]);return crumb('Dashboard','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('dashboard')+'<div class="account-main"><div class="dashboard-top"><section class="panel profile-panel"><img src="'+img('photo-1500648767791-00dcc994a43e',180)+'" alt="Customer profile"><h2>'+esc(user&&user.name||'Dianne Russell')+'</h2><p>Customer</p><a class="edit-link" href="#/account-setting">Edit Profile</a></section><section class="panel address-panel"><div class="label-muted">Billing Address</div><h3>'+esc(user&&user.name||'Dianne Russell')+'</h3><p>'+(user&&user.address?esc(user.address):'4140 Parker Rd. Allentown, New Mexico 31134')+'</p><p>'+(user&&user.email?esc(user.email):'dianne.russell@example.com')+'</p><p>(671) 555-0110</p><a class="edit-link" href="#/account-setting">Edit Address</a></section></div><section class="panel orders-panel"><div class="panel-heading"><h2>Recent Order History</h2><a class="edit-link" href="#/order-history">View All</a></div><div class="table-wrap"><table class="orders-table"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>'+rows.slice(0,5).map(function(o){return '<tr><td>#'+esc(o.id)+'</td><td>'+esc(o.date)+'</td><td><strong>'+money(o.total)+'</strong> ('+o.count+' products)</td><td><span class="status">'+esc(o.status)+'</span></td><td><a href="#/order-details?id='+esc(o.id)+'">View Details</a></td></tr>'}).join('')+'</tbody></table></div></section></div></div></main>'};
const orderHistory=function(){const arr=JSON.parse(localStorage.getItem('shopery-orders')||'[]');const rows=arr.length?arr:[{id:'738',date:'08 Sep, 2026',total:135,count:5,status:'Processing'},{id:'703',date:'24 May, 2026',total:25,count:1,status:'On the way'},{id:'130',date:'22 Apr, 2026',total:250,count:4,status:'Completed'}];return crumb('Order History','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('orders')+'<section class="panel orders-panel"><div class="panel-heading"><h2>Order History</h2><span style="font-size:11px;color:#888">'+rows.length+' orders</span></div><div class="table-wrap"><table class="orders-table"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>'+rows.map(function(o){return '<tr><td>#'+esc(o.id)+'</td><td>'+esc(o.date)+'</td><td>'+money(o.total)+' ('+o.count+' products)</td><td><span class="status">'+esc(o.status)+'</span></td><td><a href="#/order-details?id='+esc(o.id)+'">View Details</a></td></tr>'}).join('')+'</tbody></table></div></section></div></main>'};
const orderDetails=function(){const id=params().get('id')||'738';return crumb('Order Details','Account › Order History ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('orders')+'<section class="panel" style="padding:22px"><div class="panel-heading" style="padding:0 0 16px"><h2>Order #'+esc(id)+'</h2><span class="status">Processing</span></div><div class="checkout-steps"><span class="active">● Order placed</span><span class="active">● Processing</span><span>○ On the way</span><span>○ Delivered</span></div><div class="table-wrap"><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th></tr></thead><tbody>'+cartItemsForDetails()+'</tbody></table></div><div style="max-width:360px;margin:20px 0 0 auto"><div class="summary-row"><span>Subtotal</span><span>'+money(total()||45.97)+'</span></div><div class="summary-row"><span>Shipping</span><span>Free</span></div><div class="summary-row total"><span>Total</span><span>'+money(total()||45.97)+'</span></div></div></section></div></main>'};
const cartItemsForDetails=function(){const lines=cart.length?cart:[{id:1,qty:1,price:14.99},{id:2,qty:2,price:12.99}];return lines.map(function(i){const p=product(i.id);return '<tr><td><div class="cart-product"><img src="'+img(p.img,140)+'"><strong>'+esc(p.name)+'</strong></div></td><td>'+money(i.price)+'</td><td>'+i.qty+'</td><td>'+money(i.price*i.qty)+'</td></tr>'}).join('')};
const cartPage=function(){if(!cart.length)return crumb('Shopping Cart','Shop ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><p>Fill your basket with fresh market favourites.</p><a class="form-button" href="#/shop-01">Return to Shop</a></div></main>';return crumb('Shopping Cart','Shop ›')+'<main class="container inner-page two-col"><section class="panel"><div class="table-wrap"><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody>'+cart.map(function(i){const p=product(i.id);return '<tr><td><div class="cart-product"><img src="'+img(p.img,150)+'" alt=""><strong>'+esc(p.name)+'</strong></div></td><td>'+money(i.price)+'</td><td><div class="qty"><button data-change="'+p.id+'" data-delta="-1">−</button><input readonly value="'+i.qty+'"><button data-change="'+p.id+'" data-delta="1">+</button></div></td><td>'+money(i.price*i.qty)+'</td><td><button class="drawer-close" data-remove="'+p.id+'">×</button></td></tr>'}).join('')+'</tbody></table></div><div style="padding:14px"><a class="text-link" href="#/shop-01">← Continue Shopping</a></div></section><aside class="panel summary-card"><h3>Cart Total</h3><div class="summary-row"><span>Subtotal</span><strong>'+money(total())+'</strong></div><div class="summary-row"><span>Shipping</span><strong>Free</strong></div><div class="summary-row total"><span>Total</span><span>'+money(total())+'</span></div><a class="form-button" style="display:block;text-align:center;margin-top:15px" href="#/checkout">Proceed to Checkout</a></aside></main>'};
const checkout=function(){if(!cart.length)return crumb('Checkout','Shop ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><a class="form-button" href="#/shop-01">Shop Now</a></div></main>';return crumb('Checkout','Shop › Shopping Cart ›')+'<main class="container inner-page two-col"><form id="checkout-form" class="panel form-panel" style="max-width:none"><div class="checkout-steps"><span class="active">01 Billing Information</span><span>02 Shipping</span><span>03 Payment</span></div><h2>Billing Information</h2><div class="field-grid"><div class="field"><label>First name</label><input required name="first" placeholder="First name" value="'+esc(user&&user.name||'')+'"></div><div class="field"><label>Last name</label><input required name="last" placeholder="Last name"></div><div class="field full"><label>Email address</label><input required type="email" name="email" placeholder="Email address" value="'+esc(user&&user.email||'')+'"></div><div class="field full"><label>Street address</label><input required name="address" placeholder="House number and street name"></div><div class="field"><label>City</label><input required placeholder="City"></div><div class="field"><label>Postcode</label><input required placeholder="ZIP / Postal code"></div><div class="field"><label>Country</label><select><option>Pakistan</option><option>United States</option></select></div><div class="field"><label>Phone</label><input required type="tel" placeholder="Phone number"></div><div class="field full"><label>Order notes (optional)</label><textarea rows="3" placeholder="Notes about your order"></textarea></div></div><h2 style="margin-top:18px">Payment Method</h2><label class="radio-line"><input type="radio" name="payment" checked> Cash on delivery</label><label class="radio-line"><input type="radio" name="payment"> Bank transfer (demo)</label><button class="form-button" style="width:100%;margin-top:12px">Place Order</button></form><aside class="panel summary-card"><h3>Order Summary</h3>'+cart.map(function(i){const p=product(i.id);return '<div class="summary-row"><span>'+esc(p.name)+' × '+i.qty+'</span><strong>'+money(i.price*i.qty)+'</strong></div>'}).join('')+'<div class="summary-row"><span>Shipping</span><strong>Free</strong></div><div class="summary-row total"><span>Total</span><span>'+money(total())+'</span></div><p style="font-size:10px;color:#999;line-height:1.6">This static demo does not process payments or send orders to a store.</p></aside></main>'};
const accountSettings=function(){return crumb('Account Settings','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('settings')+'<div class="account-main"><form class="panel form-panel" id="settings-form" style="max-width:none"><h2>Account Settings</h2><div class="field-grid"><div class="field"><label>Full name</label><input name="name" required value="'+esc(user&&user.name||'Dianne Russell')+'"></div><div class="field"><label>Email address</label><input name="email" type="email" required value="'+esc(user&&user.email||'dianne.russell@example.com')+'"></div><div class="field full"><label>Billing address</label><input name="address" value="'+esc(user&&user.address||'4140 Parker Rd. Allentown')+'"></div><div class="field"><label>Phone number</label><input value="(671) 555-0110"></div><div class="field"><label>Country</label><select><option>Pakistan</option><option>United States</option></select></div></div><button class="form-button">Save Changes</button></form></div></div></main>'};
const wishlistPage=function(){const list=products.filter(function(p){return wishes.includes(p.id)});return crumb('Wishlist','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('wishlist')+'<section>'+(list.length?'<div class="product-grid">'+list.map(productCard).join('')+'</div>':'<div class="panel empty-state"><div class="empty-icon">♡</div><h2>Your wishlist is empty</h2><p>Save products you love and find them here later.</p><a class="form-button" href="#/shop-01">Explore Products</a></div>')+'</section></div></main>'};
const signIn=function(){return crumb('Sign In','Account ›')+'<main class="auth-wrap"><form class="auth-card" id="login-form"><h1>Sign In</h1><p class="sub">Welcome back to Shopery</p><div class="field"><label>Email</label><input name="email" type="email" required placeholder="Email address"></div><div class="field"><label>Password</label><input name="password" type="password" required placeholder="Password"></div><div style="display:flex;justify-content:space-between;align-items:center;margin:7px 0 17px"><label class="checkline"><input type="checkbox"> Remember Me</label><a class="text-link" href="#/forgot-password">Forget Password?</a></div><button class="form-button" style="width:100%">Login</button><div class="auth-foot">Don&apos;t Have Account? <a href="#/create-account">Register</a></div></form></main>'};
const createAccount=function(){return crumb('Create Account','Account ›')+'<main class="auth-wrap"><form class="auth-card" id="register-form"><h1>Create Account</h1><p class="sub">Create your Shopery account</p><div class="field"><label>Full name</label><input required name="name" placeholder="Your full name"></div><div class="field"><label>Email</label><input required name="email" type="email" placeholder="Email address"></div><div class="field"><label>Password</label><input required name="password" type="password" minlength="6" placeholder="Create a password"></div><div class="field"><label>Confirm Password</label><input required name="confirm" type="password" minlength="6" placeholder="Confirm password"></div><label class="checkline" style="margin:10px 0 17px"><input type="checkbox" required> Accept all terms & conditions</label><button class="form-button" style="width:100%">Create Account</button><div class="auth-foot">Already have an account? <a href="#/sign-in">Sign In</a></div></form></main>'};
const forgotPage=function(){return crumb('Forgot Password','Account ›')+'<main class="auth-wrap"><form class="auth-card" id="forgot-form"><h1>Forgot Password</h1><p class="sub">Enter your email to request a password reset.</p><div class="field"><label>Email</label><input name="email" type="email" required placeholder="Email address"></div><button class="form-button" style="width:100%">Send reset link</button><div class="auth-foot"><a href="#/sign-in">Back to Sign In</a></div></form></main>'};
const faqPage=function(){const q=[['What areas do you deliver to?','We deliver to our current service areas. Enter your location during checkout to confirm availability.'],['How fresh are the products?','We select produce and everyday goods with care and pack them for your chosen delivery window.'],['Can I change an order after placing it?','Contact customer service as soon as possible. Changes depend on whether the order has already been packed.'],['What payment methods are available?','This demo shows cash on delivery and bank transfer options. Connect a payment provider to process real payments.'],['What if an item is missing or damaged?','Contact our support team with your order number and we will help arrange a suitable resolution.']];return crumb('Frequently Asked Questions','Help ›')+'<main class="container inner-page" style="max-width:850px">'+q.map(function(x,i){return '<div class="faq-item '+(i===0?'open':'')+'"><button class="faq-question" data-faq>'+x[0]+'<span>＋</span></button><div class="faq-answer">'+x[1]+'</div></div>'}).join('')+'</main>'};
const aboutPage=function(){return crumb('About Us','Pages ›')+'<main class="container inner-page"><div class="product-detail" style="align-items:center"><div class="detail-image"><img src="'+img('photo-1500382017468-9049fed747ef',1000)+'"></div><div class="detail-copy"><div class="section-overline">OUR STORY</div><h1>Good food, thoughtfully brought to your table.</h1><p>Shopery brings fresh produce and everyday market favourites together in one easy place. We partner with growers and makers who care about how good food is grown, packed and shared.</p><p>Our team believes grocery shopping should feel simple, inspiring and dependable—from choosing your favourite products to receiving them at your door.</p><a class="shop-button" href="#/shop-01">Shop Our Market →</a></div></div>'+benefits()+'</main>'};
const contactPage=function(){return crumb('Contact Us','Pages ›')+'<main class="container inner-page two-col"><section class="panel form-panel" style="max-width:none"><h2>Leave a Message</h2><form id="contact-form"><div class="field-grid"><div class="field"><label>Your name</label><input required placeholder="Name"></div><div class="field"><label>Email address</label><input required type="email" placeholder="Email"></div><div class="field full"><label>Subject</label><input required placeholder="How can we help?"></div><div class="field full"><label>Message</label><textarea required rows="5" placeholder="Write your message"></textarea></div></div><button class="form-button">Send Message</button></form></section><aside class="panel form-panel" style="max-width:none"><h2>Contact Information</h2><p style="font-size:12px;color:#777;line-height:1.8">Our customer support team is here to help with orders, delivery and product questions.</p><p style="font-size:12px;line-height:2">☎ &nbsp;(219) 555-0114<br>✉ &nbsp;hello@shopery.example<br>⌖ &nbsp;Lincoln-344, Chicago, USA<br>◷ &nbsp;Monday–Saturday, 9am–6pm</p><div style="height:180px;background:#eef4eb;display:grid;place-items:center;color:#69796a">Shopery Market Location</div></aside></main>'};
const blogList=function(){return crumb('Blog List','Blog ›')+'<main class="container inner-page"><div class="blog-grid">'+blogCards()+blogCards()+'</div></main>'};
const singleBlog=function(){const a=articles[Number(params().get('id')||0)%articles.length];return crumb('Single Blog','Blog ›')+'<main class="container inner-page" style="max-width:850px"><img style="width:100%;height:370px;object-fit:cover;border-radius:5px" src="'+img(a.img,1200)+'"><div style="padding:20px 4px"><small class="section-overline">'+a.date+' · FOOD & LIFESTYLE</small><h1 style="font-size:26px;font-weight:600">'+a.title+'</h1><p style="font-size:13px;line-height:1.9;color:#777">'+a.text+' Shopery believes a thoughtful meal starts with simple, fresh ingredients. Explore the market for seasonal favourites and make them your own.</p><a href="#/blog-list" class="text-link">← Back to blog</a></div></main>'};
const trackPage=function(){return crumb('Track Order','Account ›')+'<main class="container inner-page"><form class="panel form-panel" id="track-form"><h2>Track Your Order</h2><p style="font-size:12px;color:#888">Enter your order number and email address to view the latest delivery update.</p><div class="field-grid"><div class="field"><label>Order ID</label><input required placeholder="e.g. #738"></div><div class="field"><label>Email address</label><input type="email" required placeholder="Email address"></div></div><button class="form-button">Track Order</button><div id="track-result" style="display:none;margin-top:20px;padding:16px;background:#f1f8f1;font-size:12px">Your order is being prepared. This is sample tracking information for the demo.</div></form></main>'};
const orderSuccess=function(){const id=params().get('id')||localStorage.getItem('shopery-last-order')||'SP-1001';return crumb('Order Placed','Checkout ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">✓</div><h2>Thank you for your order!</h2><p>Your order reference is <strong>#'+esc(id)+'</strong>. You can follow updates from your dashboard.</p><a class="form-button" href="#/order-history">View Order History</a></div></main>'};
const infoPage=function(title,body){return crumb(title,'Pages ›')+'<main class="container inner-page"><article class="panel info-content" style="padding:25px"><p>'+body+'</p><h2>Our commitment</h2><p>We aim to make shopping for fresh groceries straightforward and dependable. If you need help, our customer service team is ready to assist.</p></article></main>'};
const render=function(){const r=route();let body='';if(r==='home-02'||r==='home'||r==='home-01')body=home();else if(r==='shop-01'||r==='shop-02')body=shop();else if(r==='product-details')body=productPage();else if(r==='dashboard')body=dashboard();else if(r==='order-history')body=orderHistory();else if(r==='order-details')body=orderDetails();else if(r==='account-setting')body=accountSettings();else if(r==='shopping-cart')body=cartPage();else if(r==='checkout')body=checkout();else if(r==='wishlist')body=wishlistPage();else if(r==='sign-in')body=signIn();else if(r==='create-account')body=createAccount();else if(r==='forgot-password')body=forgotPage();else if(r==='faq')body=faqPage();else if(r==='about')body=aboutPage();else if(r==='contact')body=contactPage();else if(r==='blog-list')body=blogList();else if(r==='single-blog')body=singleBlog();else if(r==='track-order')body=trackPage();else if(r==='order-success')body=orderSuccess();else if(r==='terms')body=infoPage('Terms & Conditions','These demo terms describe a sample storefront only. Set your real store policies before accepting customer orders.');else if(r==='privacy')body=infoPage('Privacy Policy','This static demo stores sample preferences and cart details in your browser. It does not transmit personal information to a server.');else body=crumb('Page Not Found','')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">404</div><h2>Page not found</h2><a class="form-button" href="#/home-02">Back to home</a></div></main>';document.getElementById('app').innerHTML=header()+body+footer()+drawer();wire();};
const toast=function(message){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)}t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(function(){t.classList.remove('show')},2300)};
const addCart=function(id,qty){const p=product(id),line=cart.find(function(x){return x.id===p.id});if(line)line.qty+=qty||1;else cart.push({id:p.id,qty:qty||1,price:p.price});save();render();toast(p.name+' added to cart');const d=document.getElementById('drawer-screen');if(d)d.classList.add('open')};
const changeQty=function(id,delta){const item=cart.find(function(x){return x.id===Number(id)});if(!item)return;item.qty+=delta;if(item.qty<=0)cart=cart.filter(function(x){return x.id!==Number(id)});save();render()};
const wire=function(){document.querySelectorAll('[data-add]').forEach(function(b){b.addEventListener('click',function(){const qty=b.hasAttribute('data-detail-add')?Math.max(1,Number(document.getElementById('product-qty').value)||1):1;addCart(b.dataset.add,qty)})});document.querySelectorAll('[data-wish]').forEach(function(b){b.addEventListener('click',function(){const id=Number(b.dataset.wish);if(wishes.includes(id))wishes=wishes.filter(function(x){return x!==id});else wishes.push(id);save();render();toast(wishes.includes(id)?'Added to wishlist':'Removed from wishlist')})});document.querySelectorAll('[data-change]').forEach(function(b){b.addEventListener('click',function(){changeQty(b.dataset.change,Number(b.dataset.delta))})});document.querySelectorAll('[data-remove]').forEach(function(b){b.addEventListener('click',function(){cart=cart.filter(function(x){return x.id!==Number(b.dataset.remove)});save();render()})});const sf=document.getElementById('search-form');if(sf)sf.addEventListener('submit',function(e){e.preventDefault();window.shopSearch=document.getElementById('search-input').value.trim();nav('shop-01')});const cat=document.getElementById('all-categories');if(cat)cat.addEventListener('click',function(){nav('shop-01')});const mt=document.getElementById('mobile-toggle');if(mt)mt.addEventListener('click',function(){document.getElementById('nav-links').classList.toggle('mobile-open')});document.querySelectorAll('[data-slide]').forEach(function(b){b.addEventListener('click',function(){slideIndex=Number(b.dataset.slide);document.querySelectorAll('.hero-slide').forEach(function(s,i){s.classList.toggle('active',i===slideIndex)});document.querySelectorAll('[data-slide]').forEach(function(d,i){d.classList.toggle('active',i===slideIndex)})})});const sort=document.getElementById('sort-select');if(sort){sort.value=window.shopSort||'featured';sort.addEventListener('change',function(){window.shopSort=sort.value;render()})}document.querySelectorAll('[data-quantity]').forEach(function(b){b.addEventListener('click',function(){const q=document.getElementById('product-qty');q.value=Math.max(1,Number(q.value)+Number(b.dataset.quantity))})});document.querySelectorAll('[data-faq]').forEach(function(b){b.addEventListener('click',function(){b.parentElement.classList.toggle('open')})});document.querySelectorAll('.newsletter-form').forEach(function(f){f.addEventListener('submit',function(e){e.preventDefault();toast('Thanks for subscribing!');f.reset()})});const close=document.getElementById('drawer-close');if(close)close.addEventListener('click',function(){document.getElementById('drawer-screen').classList.remove('open')});const screen=document.getElementById('drawer-screen');if(screen)screen.addEventListener('click',function(e){if(e.target===screen)screen.classList.remove('open')});const login=document.getElementById('login-form');if(login)login.addEventListener('submit',function(e){e.preventDefault();const f=new FormData(login);user={name:f.get('email').split('@')[0],email:f.get('email')};localStorage.setItem('shopery-user',JSON.stringify(user));nav('dashboard');toast('Signed in for this demo')});const reg=document.getElementById('register-form');if(reg)reg.addEventListener('submit',function(e){e.preventDefault();const f=new FormData(reg);if(f.get('password')!==f.get('confirm')){toast('Passwords do not match');return}user={name:f.get('name'),email:f.get('email')};localStorage.setItem('shopery-user',JSON.stringify(user));nav('dashboard');toast('Account created for this demo')});const settings=document.getElementById('settings-form');if(settings)settings.addEventListener('submit',function(e){e.preventDefault();const f=new FormData(settings);user={name:f.get('name'),email:f.get('email'),address:f.get('address')};localStorage.setItem('shopery-user',JSON.stringify(user));render();toast('Profile saved in this browser')});const checkoutForm=document.getElementById('checkout-form');if(checkoutForm)checkoutForm.addEventListener('submit',function(e){e.preventDefault();const f=new FormData(checkoutForm);const order={id:String(Math.floor(1000+Math.random()*9000)),date:new Date().toLocaleDateString('en',{day:'2-digit',month:'short',year:'numeric'}),total:total(),count:cartQty(),status:'Processing'};const orders=JSON.parse(localStorage.getItem('shopery-orders')||'[]');orders.unshift(order);localStorage.setItem('shopery-orders',JSON.stringify(orders));localStorage.setItem('shopery-last-order',order.id);cart=[];save();nav('order-success?id='+order.id)});const forgot=document.getElementById('forgot-form');if(forgot)forgot.addEventListener('submit',function(e){e.preventDefault();toast('If the address is registered, reset instructions will be sent.');});const cf=document.getElementById('contact-form');if(cf)cf.addEventListener('submit',function(e){e.preventDefault();toast('Thanks for contacting us.');cf.reset()});const tf=document.getElementById('track-form');if(tf)tf.addEventListener('submit',function(e){e.preventDefault();document.getElementById('track-result').style.display='block'});document.querySelectorAll('[data-logout]').forEach(function(b){b.addEventListener('click',function(){localStorage.removeItem('shopery-user');user=null;toast('You have been signed out')})})};
window.addEventListener('hashchange',function(){render();window.scrollTo(0,0)});render();
